<?php
function final_count_is($value){$b=is_array($value)?$value:count_batch($value);return ($b['workflow_version']??'')==='5.4.29';}
function final_count_meta($b){return json_decode($b['filter_json'],true)?:[];}
function final_count_owner($b){adjustment_access();if(current_user()['role']!=='Admin'&&(int)$b['created_by']!==current_user()['id'])throw new Exception('Only the preparer or an Admin may validate, submit or cancel this count attempt.');}
function final_count_open($id,$lock=false){$q=db()->prepare('SELECT * FROM inventory_count_batches WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute([$id]);$b=$q->fetch();if(!$b||!final_count_is($b)||in_array($b['status'],['Applied','Cancelled','Reversed'],true))throw new Exception('This final-count attempt is closed.');return $b;}
function final_count_cutoff_events($pid,$b){$historical=final_count_meta($b)['historical']??false;return array_values(array_filter(inventory_ledger($pid),fn($e)=>$e['date']<$b['count_date']||($e['date']===$b['count_date']&&($historical||$e['time']<=$b['cutoff_at']))));}
function final_count_conditions_at($pid,$b){$c=['good'=>0,'packaging'=>0,'damaged'=>0,'other'=>0];foreach(final_count_cutoff_events($pid,$b) as $e){$c['good']+=(int)$e['sellable'];if(!$e['restricted'])continue;if($e['source']==='non_sellable'){$q=db()->prepare('SELECT condition_type FROM non_sellable WHERE id=?');$q->execute([$e['source_id']]);$kind=packaging_kind($q->fetchColumn());$key=$kind==='packaging'?'packaging':($kind==='damaged'?'damaged':'other');$c[$key]+=(int)$e['restricted'];}elseif($e['source']==='nonsellable_outflows'){$q=db()->prepare('SELECT l.qty,n.condition_type FROM nonsellable_release_links l JOIN non_sellable n ON n.id=l.non_sellable_id WHERE l.release_id=?');$q->execute([$e['source_id']]);$linked=0;foreach($q as $link){$kind=packaging_kind($link['condition_type']);$key=$kind==='packaging'?'packaging':($kind==='damaged'?'damaged':'other');$c[$key]-=(int)$link['qty'];$linked+=(int)$link['qty'];}$left=-(int)$e['restricted']-$linked;foreach(['damaged','other','packaging'] as $key){$take=$left<0?$left:min(max(0,$c[$key]),$left);$c[$key]-=$take;$left-=$take;if(!$left)break;}if($left)$c['other']-=$left;}}return $c;}
function final_count_signature($pid,$b){return hash('sha256',json_encode(final_count_cutoff_events($pid,$b)));}
function final_count_related($parent,$previous){$seen=[];while($parent&&!isset($seen[$parent])){if((int)$parent===(int)$previous)return true;$seen[$parent]=true;$parent=(int)(final_count_meta(count_batch($parent))['supersedes']??0);}return false;}
function final_count_create($input){adjustment_access();$input=array_intersect_key($input,array_flip(['count_date','count_scope','cutoff_ack','product_ids','entry_method','supersedes','q','brand','main_category','subcategory','status']));$date=process_date($input['count_date']??date('Y-m-d'));require_open_inventory_date($date);$scope=$input['count_scope']??'Sellable';if(!in_array($scope,['Sellable','All Conditions'],true))throw new Exception('Choose Sellable Only or All Stock Conditions.');if(empty($input['cutoff_ack']))throw new Exception('Confirm that counts represent the selected cutoff and counting-period movements are accounted for.');
 return process_transaction(function()use($input,$date,$scope){$parent=(int)($input['supersedes']??0);if($parent){$previous=count_batch($parent);final_count_owner($previous);if(!in_array($previous['status'],['Cancelled','Reversed'],true))throw new Exception('Close the previous attempt, or complete its linked reversal, before a replacement attempt.');}
  $preserveCutoff=$parent&&$previous['count_date']===$date&&!empty($previous['cutoff_at']);$input['count_date']=$date;$input['count_scope']=$scope;$input['historical']=$preserveCutoff?(final_count_meta($previous)['historical']??($date<date('Y-m-d'))):($date<date('Y-m-d'));$input['supersedes']=$parent;$id=count_create_snapshot_legacy($input);$cutoff=$preserveCutoff?$previous['cutoff_at']:($input['historical']?$date.' 23:59:59':date('Y-m-d H:i:s'));db()->prepare('UPDATE inventory_count_batches SET workflow_version=?,cutoff_at=?,rule_json=?,filter_json=? WHERE id=?')->execute(['5.4.29',$cutoff,json_encode(adjustment_rule()),json_encode($input),$id]);$b=count_batch($id);
  foreach(count_lines($id) as $l){$pid=(int)$l['product_id'];$q=db()->prepare("SELECT b.batch_ref FROM inventory_count_batches b JOIN inventory_count_lines l ON l.batch_id=b.id WHERE l.product_id=? AND b.id<>? AND b.status NOT IN ('Applied','Cancelled','Reversed') LIMIT 1");$q->execute([$pid,$id]);if($other=$q->fetchColumn())throw new Exception('An open count already includes this product: '.$other.'. Complete or cancel it first.');
   $q=db()->prepare('SELECT updated_at FROM beginning_balances WHERE product_id=?');$q->execute([$pid]);$begin=$q->fetchColumn();if($begin&&$begin>$cutoff)throw new Exception('Count date predates the recorded beginning balance for '.$l['master_sku'].'. A reliable historical baseline is unavailable.');$q=db()->prepare("SELECT b.id,b.status FROM inventory_count_batches b JOIN inventory_count_lines x ON x.batch_id=b.id WHERE x.product_id=? AND b.id<>? AND b.cutoff_at=? ORDER BY b.id DESC");$q->execute([$pid,$id,$cutoff]);foreach($q as $earlier){if($earlier['status']==='Applied')throw new Exception('This exact count cutoff was already posted in #'.$earlier['id'].'. Use its linked reversal before correction.');if(in_array($earlier['status'],['Cancelled','Reversed'],true)&&!final_count_related($parent,$earlier['id']))throw new Exception('Use Create Linked Corrected Attempt from #'.$earlier['id'].' for this count cutoff.');}$c=final_count_conditions_at($pid,$b);$balance=['physical'=>array_sum($c),'restricted'=>$c['packaging']+$c['damaged']+$c['other']];if(min($c['packaging'],$c['damaged'],$c['other'])<0||array_sum($c)!==$balance['physical'])throw new Exception('Restricted stock must be reconciled before counting '.$l['master_sku'].'.');db()->prepare('UPDATE inventory_count_lines SET on_hand=?,sellable_on_hand=?,nonsellable_on_hand=?,snapshot_conditions=?,stock_signature=? WHERE id=?')->execute([$balance['physical'],$c['good'],$balance['restricted'],json_encode($c),final_count_signature($pid,$b),$l['id']]);}
  if(count(count_lines($id))>9900)throw new Exception('Limit each count to 9,900 products.');adjustment_event($id,'Final count started',['cutoff'=>$cutoff,'scope'=>$scope,'supersedes'=>$parent,'movement_reconciliation_acknowledged'=>true]);audit('Create final inventory count','Inventory Count',$b['batch_ref'],'Final count; '.$scope.'; cutoff '.$cutoff.'; no mandatory recount.');return $id;
 });
}
function final_count_headers($scope){return $scope==='Sellable'?['Master SKU','Counted Quantity']:['Master SKU','Actual Good','Actual Packaging','Actual Damaged','Actual Other Restricted'];}
function final_count_export($id,$path){$b=count_batch($id);$scope=final_count_meta($b)['count_scope'];$rows=[];foreach(count_lines($id) as $l)$rows[]=array_merge([$l['master_sku']],array_fill(0,$scope==='Sellable'?1:4,''));report_write_xlsx($path,'Final Inventory Count',final_count_headers($scope),$rows,['Attempt'=>$b['batch_ref'],'Count Scope'=>$scope,'Count Cutoff'=>$b['cutoff_at'],'Instructions'=>'Final counts only. Blank means not counted; 0 means counted zero. System quantities are intentionally excluded.'],range(1,$scope==='Sellable'?1:4));}
function final_count_check($id){$b=count_batch($id);require_open_inventory_date($b['count_date']);foreach(count_lines($id) as $l){if($l['actual_count']===null)continue;$q=db()->prepare('SELECT active FROM products WHERE id=? FOR UPDATE');$q->execute([$l['product_id']]);if(!$q->fetchColumn())throw new Exception('Product is inactive: '.$l['master_sku']);if(!hash_equals($l['stock_signature'],final_count_signature($l['product_id'],$b)))throw new Exception('A posting at or before the count cutoff changed for '.$l['master_sku'].'. Close this attempt and create a linked attempt to validate against the corrected cutoff.');check_platform_alignment($l['product_id']);}}
function final_count_upload($id,$rows,$filename,$fileHash=null,$storedPath=null,$input=[]){adjustment_access();return process_transaction(function()use($id,$rows,$filename,$fileHash,$storedPath,$input){$b=final_count_open($id,true);final_count_owner($b);$q=db()->prepare('SELECT COUNT(*) FROM count_upload_evidence WHERE batch_id=?');$q->execute([$id]);$hasEvidence=(int)$q->fetchColumn();$guided=!empty(final_count_meta($b)['guided_version']);if($guided&&(!isset($input['guided_revision'])||(int)$input['guided_revision']!==(int)$b['revision']))throw new Exception('Use the guided validation form and latest revision.');if($b['status']!=='Exported'||($hasEvidence&&!$guided))throw new Exception('This attempt already has a final count. Use Cancel / Return for Correction, then a new linked attempt; the original evidence cannot be replaced.');$reason=process_reason($input['reason']??'');$reference=trim($input['support_reference']??'');if(strlen($reference)<3||strlen($reference)>255)throw new Exception('A supporting reference is required (3–255 characters).');$scope=final_count_meta($b)['count_scope'];$hash=$fileHash??hash('sha256',json_encode($rows));
  $q=db()->prepare("SELECT b.id,b.filter_json FROM count_upload_evidence e JOIN inventory_count_batches b ON b.id=e.batch_id WHERE e.file_hash=? AND b.id<>? AND b.count_date=? AND b.workflow_version='5.4.29' AND b.status NOT IN ('Cancelled','Reversed')");$q->execute([$hash,$id,$b['count_date']]);foreach($q as $old)if((final_count_meta($old)['count_scope']??'')===$scope)throw new Exception('The same count file is already active or posted for this cutoff. Open attempt #'.$old['id'].'.');
  $errors=[];$sheetMeta=[];foreach($rows as $row)if(isset($row[0],$row[1]))$sheetMeta[norm((string)$row[0])]=$row[1];foreach(['attempt'=>$b['batch_ref'],'count scope'=>$scope,'count cutoff'=>$b['cutoff_at']] as $key=>$expected)if(isset($sheetMeta[$key])&&(string)$sheetMeta[$key]!==$expected)$errors[]='Wrong or stale sheet metadata: '.$key.'. Download this attempt’s blank sheet.';$col=[];$header=null;$qtyHeaders=$scope==='Sellable'?['Counted Quantity']:array_slice(final_count_headers($scope),1);foreach($rows as $n=>$row){$keys=array_map(fn($v)=>norm((string)$v),$row);$itemColumn=null;foreach(['master sku','item code','item','product / sku','product'] as $h){$i=array_search($h,$keys,true);if($i!==false){$itemColumn=$i;break;}}if($itemColumn===null)continue;$ok=true;foreach($qtyHeaders as $h)if(!in_array(norm($h),$keys,true))$ok=false;if($ok){$header=$n;$col=array_flip($keys);$col['item']=$itemColumn;break;}}
  $known=[];foreach(count_lines($id) as $l)$known[(int)$l['product_id']]=$l;$values=[];$seen=[];if($header===null)$errors[]='Required columns: '.implode(', ',final_count_headers($scope)).'.';else foreach(array_slice($rows,$header+1) as $n=>$row){if(!array_filter($row,fn($v)=>trim((string)$v)!==''))continue;$rn=$header+$n+2;if($guided&&!array_filter(array_map(fn($h)=>trim((string)($row[$col[norm($h)]]??'')),$qtyHeaders),fn($v)=>$v!==''))continue;$code=trim((string)($row[$col['item']]??''));$pid=return_match($code);if(!$pid||!isset($known[$pid])){$errors[]='Row '.$rn.': unknown, ambiguous or out-of-scope item '.$code.'. Use Master SKU.';continue;}if(isset($seen[$pid])){$errors[]='Row '.$rn.': duplicate product.';continue;}$seen[$pid]=true;$vs=[];foreach($qtyHeaders as $h)$vs[]=trim((string)($row[$col[norm($h)]]??''));if(!array_filter($vs,fn($v)=>$v!==''))continue;if(array_filter($vs,fn($v)=>!preg_match('/^\d{1,8}$/D',$v))){$errors[]='Row '.$rn.': use non-negative whole numbers for every required count; blank is not zero.';continue;}$snap=json_decode($known[$pid]['snapshot_conditions'],true);$v=$scope==='Sellable'?array_replace($snap,['good'=>(int)$vs[0]]):array_combine(['good','packaging','damaged','other'],array_map('intval',$vs));$values[$known[$pid]['id']]=$v;}
  if(!$values&&!$errors)$errors[]='No final counts entered. Blank rows are not counted.';db()->prepare('INSERT INTO count_upload_evidence(batch_id,file_hash,filename,stored_path,stage,revision,user_id,errors_json) VALUES(?,?,?,?,?,?,?,?)')->execute([$id,$hash,basename($filename),$storedPath,'Final',$guided?(int)$b['revision']+1:$b['revision'],current_user()['id'],json_encode($errors)]);$evidenceId=(int)db()->lastInsertId();
  foreach($values as $lid=>$v)db()->prepare('UPDATE inventory_count_lines SET actual_count=?,variance=?-on_hand,actual_good=?,actual_damaged=?,final_conditions=?,remarks=? WHERE id=? AND batch_id=?')->execute([array_sum($v),array_sum($v),$v['good'],$v['damaged'],json_encode($v),$reason,$lid,$id]);
  db()->prepare("UPDATE inventory_count_batches SET status=?,revision=revision+1,filename=?,upload_hash=?,reason=?,support_reference=?,error_json=? WHERE id=?")->execute([$errors?'Error':'Validated',basename($filename),$hash,$reason,$reference,json_encode($errors),$id]);
  if(!$errors)try{final_count_check($id);$a=final_count_plan($id);$meta=final_count_meta(count_batch($id));$meta['validation_digest']=$a['digest'];db()->prepare('UPDATE inventory_count_batches SET filter_json=? WHERE id=?')->execute([json_encode($meta),$id]);}catch(Throwable $e){$errors[]=$e->getMessage();db()->prepare("UPDATE inventory_count_batches SET status='Error',error_json=? WHERE id=?")->execute([json_encode($errors),$id]);db()->prepare('UPDATE count_upload_evidence SET errors_json=? WHERE id=?')->execute([json_encode($errors),$evidenceId]);}
  adjustment_event($id,$errors?'Final validation errors':'Final count validated',['filename'=>basename($filename),'hash'=>$hash,'errors'=>$errors,'counted_lines'=>count($values),'stock_changed'=>false]);return $errors;
 });}
function final_count_plan($id){$b=count_batch($id);$rule=json_decode($b['rule_json'],true);$plans=[];foreach(count_lines($id) as $l){if($l['actual_count']===null)continue;$cutoff=json_decode($l['snapshot_conditions'],true);$count=json_decode($l['final_conditions'],true);$current=inventory_condition_balances($l['product_id']);$projected=[];$deltas=[];foreach(['good','packaging','damaged','other'] as $k){$deltas[$k]=$count[$k]-$cutoff[$k];$projected[$k]=$current[$k]+$deltas[$k];if($projected[$k]<0)throw new Exception('Count plus later movements produces negative '.$k.' stock for '.$l['master_sku'].'. Reconcile those movements before posting.');}$round=adjustment_rounding($projected['good'],$rule);$before=[];$after=[];$changes=[];foreach(['Lazada','Shopee','TikTok'] as $pl){$before[$pl]=platform_qty($pl,$l['product_id']);$after[$pl]=$round[$pl]['final'];$changes[$pl]=$after[$pl]-$before[$pl];}
  $plans[]=['line_id'=>$l['id'],'product_id'=>$l['product_id'],'sku'=>$l['master_sku'],'product'=>$l['product_name'],'cutoff_conditions'=>$cutoff,'counted'=>$count,'snapshot'=>$current,'first'=>$count,'recount'=>$projected,'remarks'=>$l['remarks'],'physical_delta'=>array_sum($deltas),'good_delta'=>$deltas['good'],'condition_deltas'=>$deltas,'before_platforms'=>$before,'final_platforms'=>$after,'platform_changes'=>$changes,'rounding'=>$round,'current_signature'=>count_stock_signature($l['product_id'])];}
 if(!$plans)throw new Exception('There are no final counted products.');return ['batch'=>$b,'lines'=>$plans,'rule'=>$rule,'digest'=>hash('sha256',json_encode([$b['revision'],$rule,$plans]))];}
function final_count_submit($id,$revision,$ack){adjustment_access();if(!$ack)throw new Exception('Acknowledge the final counts, cutoff and movements during counting.');return process_transaction(function()use($id,$revision){$b=final_count_open($id,true);final_count_owner($b);if($b['status']!=='Validated'||(int)$revision!==(int)$b['revision'])throw new Exception('Only the current validated attempt may be submitted.');final_count_check($id);$a=final_count_plan($id);$m=final_count_meta($b);if(!hash_equals($m['validation_digest']??'',$a['digest']))throw new Exception('Stock or allocation changed after validation. Cancel this attempt and create a linked attempt to review updated projections; no second physical count is automatically required.');$m['submitted_by']=current_user()['id'];$m['submitted_at']=date('Y-m-d H:i:s');$m['submitted_digest']=$a['digest'];db()->prepare("UPDATE inventory_count_batches SET status='Submitted',filter_json=? WHERE id=?")->execute([json_encode($m),$id]);adjustment_event($id,'Final count submitted',['counts_locked'=>true,'digest'=>$a['digest']]);});}
function final_count_review($id,$revision,$ack){adjustment_access();if(current_user()['role']!=='Admin')throw new Exception('Only an Admin can review requests for final approval.');if(!$ack)throw new Exception('Acknowledge the final count and projected adjustment.');return process_transaction(function()use($id,$revision){$b=final_count_open($id,true);if($b['status']!=='Submitted'||(int)$revision!==(int)$b['revision'])throw new Exception('Select the current submitted final count.');final_count_check($id);$a=final_count_plan($id);if(!hash_equals(final_count_meta($b)['submitted_digest']??'',$a['digest']))throw new Exception('Stock changed after submission. Return for correction and validate a linked replacement attempt.');$u=current_user();db()->prepare("UPDATE inventory_count_batches SET status='Awaiting Approval',reviewed_by=?,reviewed_name=?,reviewed_role=?,reviewed_at=NOW(),review_digest=? WHERE id=?")->execute([$u['id'],$u['name'],$u['role'],$a['digest'],$id]);adjustment_event($id,'Reviewed',['reviewer'=>$u['name'],'digest'=>$a['digest'],'final_count'=>true]);});}
function final_count_close($id,$reason,$return=false){adjustment_access();if($return&&current_user()['role']!=='Admin')throw new Exception('Only an Admin can return a submitted request for correction.');$reason=process_reason($reason);return process_transaction(function()use($id,$reason,$return){$b=final_count_open($id,true);if(!$return)final_count_owner($b);elseif(!in_array($b['status'],['Submitted','Awaiting Approval'],true))throw new Exception('Only a submitted count can be returned for correction.');db()->prepare("UPDATE inventory_count_batches SET status='Cancelled' WHERE id=?")->execute([$id]);adjustment_event($id,$return?'Returned for correction':'Cancelled',['reason'=>$reason,'original_evidence_preserved'=>true,'new_linked_attempt_required'=>true]);audit('Close final count attempt','Inventory Count',$b['batch_ref'],$reason);});}
function final_count_manual_save($id,$input){$b=count_batch($id);$scope=final_count_meta($b)['count_scope'];$rows=[final_count_headers($scope)];$known=array_column(count_lines($id),'id');foreach(array_keys($input['counts']??[]) as $lid)if(!in_array((int)$lid,array_map('intval',$known),true))throw new Exception('Count line is outside this attempt.');foreach(count_lines($id) as $l){$v=$input['counts'][$l['id']]??[];$row=[$l['master_sku']];foreach($scope==='Sellable'?['good']:['good','packaging','damaged','other'] as $k)$row[]=$v[$k]??'';$rows[]=$row;}return final_count_upload($id,$rows,'Manual Final Count',hash('sha256',json_encode(['Manual',$rows])),null,$input);}

function final_count_post($id,$digest,$ack){adjustment_access();if(current_user()['role']!=='Admin')throw new Exception('Admin approval required.');if(!$ack)throw new Exception('Review and acknowledge the final adjustment.');return process_transaction(function()use($id,$digest){$b=final_count_open($id,true);if($b['status']!=='Awaiting Approval')throw new Exception('This count is not awaiting approval.');access_assert_admin_approval($b['created_by']);require_open_inventory_date($b['count_date']);require_open_inventory_date(date('Y-m-d'));final_count_check($id);$a=final_count_plan($id);if(!hash_equals($b['review_digest'],$a['digest'])||!hash_equals($a['digest'],(string)$digest))throw new Exception('Review changed. Return for review before approval.');$date=$b['count_date'];$ref=$b['batch_ref'];$uid=current_user()['id'];foreach($a['lines'] as $l){$pid=$l['product_id'];$note=$b['reason'].'; '.$b['support_reference'].'; '.$l['remarks'];$gd=$l['good_delta'];if($gd>0)db()->prepare('INSERT INTO inflows(txn_date,reference_no,product_id,source_qty,source_uom,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$date,$ref,$pid,$gd,'pc',$gd,'Inventory Count Adjustment',$note,$uid]);elseif($gd<0)db()->prepare('INSERT INTO outflows(txn_date,platform,order_id,product_id,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$date,'Internal',$ref,$pid,-$gd,'Inventory Count Adjustment',$note,$uid]);
 foreach(['packaging'=>'RAW / For Packaging','damaged'=>'Damage / Leak','other'=>'Other Restricted Stocks'] as $k=>$condition){$delta=$l['recount'][$k]-$l['snapshot'][$k];if($delta>0)db()->prepare("INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id,packaging_state) VALUES(?,'Internal',?,?,?,?,'Count Adjustment','For Review','Inventory Count',0,?,?,?)")->execute([$date,$ref,$pid,$delta,$condition,$note,$uid,$k==='packaging'?'Pending':null]);elseif($delta<0)adjustment_release_condition($pid,$k,-$delta,$date,$ref,$note,$date);}
 // Physical sellable variance is placed on the largest source allocation first;
 // redistribution is a distinct zero-net platform movement afterwards.
 $intermediate=$l['before_platforms'];$physicalSplit=['Lazada'=>0,'Shopee'=>0,'TikTok'=>0];if($gd>=0){$physicalSplit['Shopee']=$gd;}else{$left=-$gd;$rank=$intermediate;arsort($rank,SORT_NUMERIC);foreach($rank as $pl=>$available){$take=min($left,max(0,$available));$physicalSplit[$pl]-=$take;$left-=$take;}if($left)$physicalSplit['Shopee']-=$left;}
 foreach($physicalSplit as $pl=>$delta)if($delta){$GLOBALS['RS8_REPORT_ACTION']='Physical Adjustment';change_platform_stock($pl,$pid,$delta,$ref,$date);unset($GLOBALS['RS8_REPORT_ACTION']);$intermediate[$pl]+=$delta;}
 $redistribution=[];foreach($l['final_platforms'] as $pl=>$target){$delta=$target-$intermediate[$pl];$redistribution[$pl]=$delta;if($delta){$GLOBALS['RS8_REPORT_ACTION']='Platform Redistribution';change_platform_stock($pl,$pid,$delta,$ref,date('Y-m-d'));unset($GLOBALS['RS8_REPORT_ACTION']);}}if(array_sum($redistribution)!==0)throw new Exception('Redistribution is not balanced.');check_platform_alignment($pid);$now=stock_row($pid);if($now['current']!==$l['recount']['good']||$now['physical']!==array_sum($l['recount']))throw new Exception('Count posting failed its stock reconciliation.');
 $posting=$l+['physical_platform_split'=>$physicalSplit,'intermediate_platforms'=>$intermediate,'redistribution'=>$redistribution];db()->prepare('UPDATE inventory_count_lines SET posting_json=? WHERE id=?')->execute([json_encode($posting),$l['line_id']]);$insert=db()->prepare('INSERT INTO adjustment_movements(batch_id,product_id,txn_date,movement_type,physical_delta,sellable_delta,platform_json,detail_json,user_id) VALUES(?,?,?,?,?,?,?,?,?)');$insert->execute([$id,$pid,$date,'Physical Adjustment',$l['physical_delta'],$gd,json_encode($physicalSplit),json_encode($posting),$uid]);$insert->execute([$id,$pid,date('Y-m-d'),'Platform Redistribution',0,0,json_encode($redistribution),json_encode(['final'=>$l['final_platforms'],'rule'=>$a['rule'],'rounding'=>$l['rounding']]),$uid]);audit('Physical count adjustment','Product',$l['sku'],$ref.'; physical delta '.$l['physical_delta'].'; sellable delta '.$gd);audit('Platform redistribution','Product',$l['sku'],$ref.'; net physical 0; '.json_encode($redistribution).'; rule '.$a['rule']['version']);}
 $u=current_user();db()->prepare("UPDATE inventory_count_batches SET status='Applied',approved_by=?,approved_name=?,approved_role=?,applied_at=NOW() WHERE id=?")->execute([$uid,$u['name'],$u['role'],$id]);adjustment_event($id,'Approved and posted',['approver'=>$u['name'],'rule'=>$a['rule'],'products'=>count($a['lines'])]);});}
